import type { Term } from './types';
import { definitionSources } from './sources';

// Original bilingual teaching text. Sources verify mathematical content, not quotations.
type Row = [string, string, string, string, string, string, string, string, string?];
// Only these concepts had their Russian terminology independently checked in the
// listed Russian section. Every explanation/example is still authored, not quoted.
const russianSourceCoverage: Record<string, string[]> = {
  ruFractions: ['Fraction', 'Numerator', 'Denominator'],
  ruExpressions: ['Expression', 'Variable', 'Substitute'],
  ruEquation: ['Equation', 'Solution'],
  ruSystems: ['Simultaneous equations'],
  ruSets: ['Intersection', 'Union'],
  ruDomain: ['Excluded value'],
  ruSigns: ['Sign chart', 'Boundary inclusion'],
  ruInequality: ['Inequality', 'Strict inequality'],
};
export const reviewedTerms: Record<string, Term> = {};
const preciseSourceKeys: Record<string, string[]> = {
  Factor: ['quadraticEquations', 'rationalExpressions'],
  Expand: ['distributive'],
  'Universal set': ['setOperations'],
  'Rational equation': ['rationalEquations'],
  Convergence: ['series', 'seriesConvergence'],
};
function group(sourceKeys: string[], rows: Row[]) {
  for (const [term, russianTerm, meaning, meaningRu, example, exampleRu, contrastEn, contrastRu, diagram] of rows) {
    const sources = (preciseSourceKeys[term] ?? sourceKeys).filter(key => definitionSources[key].language !== 'ru' || russianSourceCoverage[key]?.includes(term)).map(key => definitionSources[key]);
    reviewedTerms[term] = { term, meaning, example, ru: { term: russianTerm, meaning: meaningRu, example: exampleRu }, diagram,
      review: { englishTerm: term, russianTerm, contrast: { en: contrastEn, ru: contrastRu }, sources },
      russianEvidence: sources.some(source => source.language === 'ru') ? 'independently-checked' : 'authored-adaptation',
    };
  }
}

group(['fractions', 'ruFractions'], [
  ['Fraction', 'Дробь', 'A fraction a/b is a quotient: the numerator a is divided by the denominator b. The denominator cannot be zero, because you cannot divide by zero.', 'Дробь a/b — это частное: числитель a делят на знаменатель b. Знаменатель не может быть равен нулю, потому что на ноль делить нельзя.', 'Divide a strip into 5 equal parts and shade 3 of them. The shaded part is 3/5 of the strip. Also, 3/5 = 3 ÷ 5 = 0.6.', 'Раздели полоску на 5 равных частей и закрась 3 из них. Закрашенная часть — 3/5 полоски. Также 3/5 = 3 ÷ 5 = 0,6.', 'The parts must be equal. A fraction can be greater than 1 (such as 7/4) or negative (such as −3/4), but a picture of one whole shows only fractions from 0 to 1.', 'Части должны быть равными. Дробь может быть больше 1 (например; 7/4) или отрицательной (например; −3/4), а рисунок одного целого показывает только дроби от 0 до 1.', 'fraction'],
  ['Numerator', 'Числитель', 'The numerator is the number or expression above the fraction bar. It is the dividend, the quantity that is divided in the division the fraction shows.', 'Числитель — это число или выражение над дробной чертой. Это делимое: именно его делят в делении, которое показывает дробь.', 'In 3/5 the numerator is 3; in (x + 2)/7 the entire expression x + 2 is the numerator.', 'В 3/5 числитель — 3; в (x + 2)/7 числитель — всё выражение x + 2.', 'Do not read 3/5 as “5 out of 3”. It means 3 parts out of 5 equal parts.', 'Не читай 3/5 как «5 из 3». Это 3 части из 5 равных.', 'fraction'],
  ['Denominator', 'Знаменатель', 'The denominator is the number or expression below the fraction bar: the divisor in the fraction. For a whole-number denominator, it shows how many equal parts make one whole.', 'Знаменатель — это число или выражение под дробной чертой: делитель в дроби. Если знаменатель — целое число, он показывает, сколько равных частей составляют одно целое.', 'In 3/5 the denominator is 5, so each part is one fifth. In 2/(x − 4), the expression x − 4 must not be zero, so x ≠ 4.', 'В 3/5 знаменатель равен 5, поэтому каждая часть — одна пятая. В 2/(x − 4) выражение x − 4 не должно быть равно нулю, значит, x ≠ 4.', 'A larger denominator gives smaller equal parts of the same whole: 1/8 is smaller than 1/4.', 'Больший знаменатель даёт меньшие равные части одного и того же целого: 1/8 меньше 1/4.', 'fraction'],
]);
group(['language', 'ruExpressions'], [
  ['Expression', 'Выражение', 'A combination of numbers, variables and operation signs. It has no equals sign, and it gets a value once each variable is given a number.', 'Запись из чисел, переменных и знаков действий. В выражении нет знака равенства; оно получает значение, когда каждой переменной задают число.', 'At x = 2, the expression 4x − 3 has value 4 × 2 − 3 = 5.', 'При x = 2 выражение 4x − 3 имеет значение 4 × 2 − 3 = 5.', '4x − 3 is an expression; 4x − 3 = 5 is an equation. Evaluate or simplify an expression; solve an equation.', '4x − 3 — выражение; 4x − 3 = 5 — уравнение. Выражение вычисляют или упрощают, уравнение решают.', 'algebra'],
  ['Term', 'Слагаемое (член многочлена)', 'A part of an expression that is separated from the others by a + or − sign. The sign in front of a term belongs to that term.', 'Часть выражения, отделённая от остальных знаками «+» или «−». Знак перед слагаемым относится к нему самому.', 'Write 5x − 2y + 8 as 5x + (−2y) + 8. Its terms are 5x, −2y and 8.', 'Запиши 5x − 2y + 8 как 5x + (−2y) + 8. Слагаемые — 5x, −2y и 8.', 'In 3(x + 2), 3 and x + 2 are factors, not terms, because they are multiplied. In a sequence, a term is one of its numbers. In 2, 5, 8, the third term is 8.', 'В 3(x + 2) число 3 и выражение x + 2 — множители, а не слагаемые, потому что их перемножают. Член последовательности — одно из её чисел. В последовательности 2, 5, 8 третий член равен 8.', 'algebra'],
  ['Factor', 'Множитель', 'One of the numbers or expressions that are multiplied to give a product. To factorise an expression means to rewrite it as a product of factors.', 'Одно из чисел или выражений, которые перемножают, чтобы получить произведение. Разложить на множители — записать выражение в виде произведения множителей.', 'In 6x + 12 = 6(x + 2), the factors of 6(x + 2) are 6 and x + 2.', 'В 6x + 12 = 6(x + 2) множители в 6(x + 2) — это 6 и x + 2.', 'Cancel only common factors, never single terms: in (2x + 4)/2, cancelling just the 2 in 2x gives x + 4, but the answer is x + 2.', 'Сокращай только общие множители, но не отдельные слагаемые: в (2x + 4)/2, если сократить только двойку из 2x, получится x + 4, а верный ответ — x + 2.', 'algebra'],
  ['Variable', 'Переменная', 'A letter or symbol whose value can change within a given set of values. In an equation, it can stand for an unknown value that must be found.', 'Буква или символ, значение которого может меняться в заданном множестве значений. В уравнении переменная может обозначать неизвестное значение, которое нужно найти.', 'In P = 4s (the perimeter of a square), a side of 2 cm gives P = 8 cm, and a side of 3 cm gives P = 12 cm.', 'В P = 4s (периметр квадрата) сторона 2 см даёт P = 8 см, а сторона 3 см — P = 12 см.', 'In y = 2x, both x and y can take many values; in 4x − 3 = 9, the unknown x has only one value, 3.', 'В y = 2x могут меняться и x, и y; в 4x − 3 = 9 неизвестное x имеет только одно значение — 3.', 'algebra'],
  ['Coefficient', 'Коэффициент', 'The number that multiplies the variable part of a term, including its sign.', 'Число, на которое умножают буквенную часть слагаемого, вместе со знаком.', 'In −6x² + x − 9, the coefficient of x² is −6 and the coefficient of x is 1.', 'В −6x² + x − 9 коэффициент при x² равен −6, а при x равен 1.', 'The coefficient is −6, but the whole term is −6x². If no number is written before a letter, the coefficient is 1 (or −1 for −x).', 'Коэффициент равен −6, а всё слагаемое — −6x². Если перед буквой нет числа, коэффициент равен 1 (а для −x он равен −1).', 'algebra'],
  ['Constant', 'Постоянная величина (константа)', 'A quantity that keeps the same value in a given situation, unlike a variable. A constant term is a term that contains no variable.', 'Величина, которая в конкретной ситуации сохраняет одно и то же значение, в отличие от переменной. Свободный член — слагаемое, в котором нет переменной.', 'In the bike-hire cost C = 8 + 3h (C in AED, h in hours), the constant term is 8: it does not depend on h.', 'В формуле стоимости проката C = 8 + 3h (C в дирхамах, h в часах) свободный член 8 — постоянная величина: он не зависит от h.', 'A constant can be written with a letter: in y = kx, k may be fixed while x and y vary.', 'Константу можно обозначить буквой: в y = kx число k может быть фиксировано, хотя x и y меняются.', 'algebra'],
  ['Substitute', 'Подстановка', 'Substituting means replacing a variable with a given value wherever it appears. Everything else stays unchanged.', 'Подстановка — это замена переменной заданным значением во всех местах, где она стоит. Всё остальное не меняется.', 'For x = −3, 2x² − 1 = 2(−3)² − 1 = 17.', 'При x = −3 получается 2x² − 1 = 2(−3)² − 1 = 17.', 'Put a negative value in brackets: (−3)² is 9, but −3² means −(3²), which is −9.', 'Отрицательное значение подставляй в скобках: (−3)² равно 9, а −3² означает −(3²), то есть −9.'],
  ['Expand', 'Раскрыть скобки', 'To expand brackets, multiply the number or expression outside by every term inside, using the distributive law.', 'Раскрыть скобки — умножить число или выражение перед скобками на каждое слагаемое внутри них по распределительному закону (distributive law).', '−3(2x − 5) = (−3)(2x) + (−3)(−5) = −6x + 15.', '−3(2x − 5) = (−3)(2x) + (−3)(−5) = −6x + 15.', 'Multiply every term inside the brackets: 3(x + 2) = 3x + 6, not 3x + 2. Expanding changes the form, not the value.', 'Умножай каждое слагаемое внутри скобок: 3(x + 2) = 3x + 6, а не 3x + 2. Раскрытие скобок меняет запись, но не значение.'],
  ['Like terms', 'Подобные слагаемые', 'Terms with identical variable factors raised to identical powers; only their coefficients may differ.', 'Слагаемые с одинаковой буквенной частью, включая степени переменных; различаться могут их коэффициенты.', '7ab − 2ab = 5ab, but 7a + 2a² cannot be combined into one like term.', '7ab − 2ab = 5ab, но 7a + 2a² нельзя привести к одному подобному слагаемому.', 'Constants are like terms with each other. The variable order does not matter: xy and yx have the same variable part.', 'Числовые слагаемые подобны друг другу. Порядок букв не важен: xy и yx имеют одинаковую буквенную часть.'],
]);
group(['equations', 'ruEquation'], [
  ['Equation', 'Уравнение', 'A statement that two expressions are equal. In an equation with an unknown, solving means finding every value of the unknown that makes the statement true.', 'Утверждение, что два выражения равны. Уравнение с неизвестным решают, находя все значения неизвестного, при которых равенство верно.', '4x − 3 = 9: add 3 to both sides to get 4x = 12, then divide both sides by 4 to get x = 3.', '4x − 3 = 9: прибавь 3 к обеим частям и получи 4x = 12; раздели обе части на 4 и получи x = 3.', 'In English, an equation can also be a statement with no unknown, such as 2 + 3 = 5.', 'В английском «equation» может обозначать и запись без неизвестного, например 2 + 3 = 5. По-русски такую запись называют числовым равенством, а уравнением называют равенство с неизвестным.', 'algebra'],
  ['Equivalent', 'Равносильный (тождественно равный)', 'Equivalent equations have exactly the same solutions on the stated domain. Equivalent expressions have the same value for every value of the variable within their domain.', 'Равносильные уравнения имеют одни и те же решения на заданной области определения. Тождественно равные выражения имеют одно и то же значение при всех значениях переменной из области определения.', '2x + 6 = 10 and x = 2 are equivalent over ℝ. Also 2(x + 3) and 2x + 6 are equivalent expressions.', '2x + 6 = 10 и x = 2 равносильны на ℝ. Выражения 2(x + 3) и 2x + 6 тождественно равны.', 'Restrictions matter: x/x = 1 only when x ≠ 0. Squaring both sides of x = 2 gives x² = 4, which also has the solution −2, so the two equations are not equivalent.', 'Ограничения важны: x/x = 1 только при x ≠ 0. Если возвести обе части уравнения x = 2 в квадрат, получится уравнение x² = 4. У него есть ещё корень −2, поэтому уравнения не равносильны.'],
  ['Linear equation', 'Линейное уравнение', 'A linear equation is an equation in which each variable appears only to the power 1, with no x², no xy and no variable in a denominator.', 'Линейное уравнение — уравнение, в котором каждая переменная стоит только в первой степени: без x², без произведений переменных и без переменной в знаменателе.', '3(x − 2) = 9 becomes 3x − 6 = 9, so x = 5. In two variables, 2x + y = 4 is linear.', '3(x − 2) = 9 приводится к 3x − 6 = 9, откуда x = 5. Уравнение 2x + y = 4 линейно по двум переменным.', 'x² = 4 and 1/x = 2 are not linear: x is squared in the first and sits in a denominator in the second.', 'x² = 4 и 1/x = 2 не линейны: в первом x возведён в квадрат, во втором x стоит в знаменателе.'],
  ['Solution', 'Решение; корень уравнения', 'A solution of an equation is a value of the variable that makes both sides equal when substituted.', 'Решение уравнения — значение переменной, при подстановке которого обе части становятся равными.', 'x = 4 is a solution of 2x + 1 = 9, because 2 × 4 + 1 = 9; x = 3 is not, because 2 × 3 + 1 = 7.', 'x = 4 — решение уравнения 2x + 1 = 9, так как 2 × 4 + 1 = 9; x = 3 — не решение, так как 2 × 3 + 1 = 7.', 'Write the answer as x = 4, not 9: 9 is the number on the other side of the equation.', 'Ответ записывай как x = 4, а не 9: число 9 стоит в другой части уравнения.'],
  ['Inverse operation', 'Обратное действие', 'An inverse operation is an operation that undoes another one: subtraction undoes addition, and division undoes multiplication.', 'Обратное действие — действие, которое отменяет другое: вычитание отменяет сложение, а деление отменяет умножение.', 'To undo multiplying x by 5, divide by 5: 5x = 20 gives x = 4.', 'Чтобы отменить умножение x на 5, делим на 5: из 5x = 20 получаем x = 4.', 'Multiplying both sides by 0 is not an equivalence transformation: 2x = 6 would become 0 = 0, which is true for any x. Such an operation cannot be undone.', 'Умножение обеих частей на 0 — не равносильное преобразование (equivalence transformation): из 2x = 6 получится 0 = 0, а это верно при любом x. Такое действие нельзя отменить.'],
  ['Subject of a formula', 'Выражение переменной из формулы', 'The variable that stands alone on one side of a formula, with no copy of it on the other side.', 'Переменная, которая стоит отдельно в одной части формулы; в другой части её быть не должно.', 'The area of a triangle is A = bh/2, where b is the base and h is the height. Make h the subject: 2A = bh, so h = 2A/b, where b ≠ 0. For A = 12 cm² and b = 4 cm, h = 2 × 12 ÷ 4 = 6 cm.', 'Площадь треугольника: A = bh/2, где b — основание, h — высота. Вырази h: 2A = bh, значит h = 2A/b, где b ≠ 0. При A = 12 см² и b = 4 см получается h = 2 × 12 ÷ 4 = 6 см.', 'Changing the subject gives a new rule in other variables, not one number. Solving 2x − 7 = 8 gives one value: x = 7.5.', 'Выражение переменной из формулы даёт новое правило с другими величинами, а не одно число. Решая уравнение 2x − 7 = 8, получается одно значение: x = 7,5.'],
]);
group(['inequalities', 'ruInequality'], [
  ['Inequality', 'Неравенство', 'A statement that compares two expressions using <, >, ≤ or ≥. Its solutions are the values that make the comparison true.', 'Утверждение, которое сравнивает два выражения знаками <, >, ≤ или ≥. Решения неравенства — значения, при которых это сравнение верно.', 'Solving 2x + 1 < 7 gives x < 3. For example, x = 2 is a solution, but x = 3 is not.', 'Из 2x + 1 < 7 получается x < 3. Например, x = 2 — решение, а x = 3 — нет.', 'An equation says that two expressions are equal. An inequality says that one is smaller or larger. Note that ≤ and ≥ also allow equality.', 'Уравнение утверждает, что два выражения равны. Неравенство утверждает, что одно из них меньше или больше другого. Знаки ≤ и ≥ допускают и равенство.', 'inequality'],
  ['Linear inequality', 'Линейное неравенство', 'An inequality in which the variable appears only to the first power, such as ax + b < 0 in one variable.', 'Неравенство, в котором переменная входит только в первой степени, например ax + b < 0 для одной переменной.', '3x + 4 > 10 gives 3x > 6, so x > 2. Check: x = 3 gives 13 > 10, which is true, but x = 1 gives 7 > 10, which is false.', '3x + 4 > 10 даёт 3x > 6, значит x > 2. При x = 3 получаем 13 > 10 — верно, а при x = 1 получаем 7 > 10 — неверно.', 'Do not confuse it with an equation: 5 − 2x = 11 has one solution, x = −3, but 5 − 2x < 11 gives an interval of values, x > −3.', 'Не путай с уравнением: у уравнения 5 − 2x = 11 одно решение, x = −3, а у неравенства 5 − 2x < 11 получается промежуток значений, x > −3.', 'inequality'],
  ['Strict inequality', 'Строгое неравенство', 'An inequality that uses < or >. Values that make the two sides equal do not satisfy it.', 'Неравенство со знаком < или >. Значения, при которых обе части равны, не подходят.', 'x > −3 is true for −2.9 and 0, but false for −3 itself.', 'Неравенство x > −3 верно для −2,9 и 0, но неверно для самого −3.', 'A strict inequality is not the same as ≠: x ≠ −3 excludes one value, but x > −3 excludes every value at or below −3.', 'Строгое неравенство — не то же, что «не равно» (≠): x ≠ −3 исключает одно число, а x > −3 исключает все числа, которые меньше −3 или равны −3.', 'inequality'],
  ['Inclusive inequality', 'Нестрогое неравенство', 'An inequality that uses ≤ or ≥. It is true when the two sides are equal, as well as when the strict inequality (< or >) holds.', 'Неравенство со знаком ≤ или ≥. Оно верно, если обе части равны, а также если верно соответствующее строгое неравенство (< или >).', 'x ≤ 4 includes x = 4, because 4 ≤ 4 is true, but it excludes x = 5, because 5 ≤ 4 is false.', 'x ≤ 4 включает x = 4, потому что 4 ≤ 4 — верно, но не включает x = 5, потому что 5 ≤ 4 — неверно.', 'Do not confuse ≤ with <: x ≤ 4 includes 4, but x < 4 does not.', 'Не путай ≤ и <: x ≤ 4 включает 4, а x < 4 — нет.', 'inequality'],
  ['Solution set', 'Множество решений', 'The set of all values of the variable that make the inequality true.', 'Множество всех значений переменной, при которых неравенство верно.', 'Over the real numbers, 3x ≤ 6 gives x ≤ 2. Check: x = 2 gives 6 ≤ 6, which is true, but x = 3 gives 9 ≤ 6, which is false. Over the integers, the solution set is 2, 1, 0, −1 and so on.', 'На действительных числах 3x ≤ 6 даёт x ≤ 2. При x = 2 получаем 6 ≤ 6 — верно, а при x = 3 получаем 9 ≤ 6 — неверно. На целых числах множество решений: 2, 1, 0, −1 и так далее.', 'Do not confuse the allowed values with the solution set: the allowed values are the numbers you may test (for example, only integers), but the solution set is the part of them that makes the inequality true.', 'Не путай допустимые значения (allowed values) и множество решений. Допустимые значения — это числа, которые можно подставлять (например, только целые). Множество решений — та их часть, при которой неравенство верно.'],
  ['Compound inequality', 'Составное неравенство', 'Two or more inequalities joined by “and” or “or”. With “and”, all the conditions must hold at the same time. A double inequality, such as −1 < x ≤ 4, is a short way of writing two conditions joined by “and”: x > −1 and x ≤ 4.', 'Два или несколько неравенств, соединённых словами «и» или «или». При «и» все условия выполняются одновременно. Двойное неравенство, например −1 < x ≤ 4, — короткая запись двух условий, соединённых словом «и»: x > −1 и x ≤ 4.', '−1 < x ≤ 4 means x > −1 AND x ≤ 4. Check: x = 4 satisfies both parts, but x = −1 fails the first part, since −1 < −1 is false.', '−1 < x ≤ 4 означает x > −1 И x ≤ 4. При x = 4 выполнены обе части, а при x = −1 не выполнена первая: −1 < −1 — неверно.', '“x < 0 or x > 2” has two separate parts, so it cannot be written as one double inequality. Written as 2 < x < 0, it would have no solutions.', '«x < 0 или x > 2» состоит из двух отдельных частей, поэтому одним двойным неравенством его не записать. Если записать 2 < x < 0, решений не будет.'],
]);

group(['statements', 'proof'], [
  ['Generalisation', 'Обобщение', 'A statement extending a property to an entire specified class of cases, rather than only the examples observed.', 'Утверждение, распространяющее свойство на весь указанный класс случаев, а не только на проверенные примеры.', 'The sums 3 + 4 + 5 = 12, 4 + 5 + 6 = 15 and 10 + 11 + 12 = 33 are all divisible by 3. So propose that n + (n + 1) + (n + 2) is divisible by 3 for every integer n.', 'Суммы 3 + 4 + 5 = 12, 4 + 5 + 6 = 15 и 10 + 11 + 12 = 33 делятся на 3. Значит, можно предположить, что n + (n + 1) + (n + 2) делится на 3 при любом целом n.', 'A pattern suggests a generalisation; a proof must justify every case in its stated scope.', 'Закономерность наводит на обобщение, но доказательство должно охватить все случаи, о которых сказано в утверждении.'],
  ['Conjecture', 'Гипотеза', 'A mathematical statement that is believed to be true but has not yet been proved. Once it is proved, it is usually called a theorem.', 'Математическое утверждение, которое считают верным, но которое ещё не доказано. После доказательства его обычно называют теоремой.', 'Seeing 1 + 3 = 4 and 1 + 3 + 5 = 9 suggests that the first n positive odd integers sum to n².', 'Равенства 1 + 3 = 4 и 1 + 3 + 5 = 9 подсказывают: сумма первых n положительных нечётных чисел равна n².', 'A conjecture that is not yet proved is not automatically false. It is false only if a valid counterexample exists.', 'Гипотеза, которая ещё не доказана, не обязательно ложна. Она ложна, только если существует допустимый контрпример.'],
  ['Proof', 'Доказательство', 'A chain of valid logical deductions from definitions, accepted results and stated assumptions that establishes the claim.', 'Цепочка верных логических выводов из определений, известных результатов и заданных допущений, которая обосновывает утверждение.', 'Let the two consecutive integers be n and n + 1. Their sum is 2n + 1, so it is odd for every integer n.', 'Пусть два последовательных целых числа — n и n + 1. Их сумма равна 2n + 1, значит, она нечётна при любом целом n.', 'Substituting one number, such as n = 4, checks a single case. A proof works with n as any integer, so it covers every case.', 'Подстановка одного числа, например n = 4, проверяет только один случай. Доказательство работает с n как с любым целым, поэтому охватывает все случаи.'],
  ['Counterexample', 'Контрпример', 'A case within the stated assumptions for which a universal claim is false.', 'Допустимый случай, при котором утверждение «для всех» оказывается ложным.', 'The prime number 2 is even, so it refutes “every prime number is odd”.', 'Простое число 2 чётно, поэтому оно опровергает утверждение «каждое простое число нечётно».', 'An example outside the assumptions proves nothing about the claim; one counterexample refutes “all”, not necessarily “some”.', 'Пример вне условий ничего не говорит об утверждении; один контрпример опровергает «все», но не обязательно «некоторые».'],
]);
group(['integers', 'sequences'], [
  ['Integer', 'Целое число', 'A whole number that is positive, negative or zero. The integers are written as ℤ = {…, −2, −1, 0, 1, 2, …}.', 'Целое число — это число, которое может быть положительным, отрицательным или нулём. Множество целых чисел обозначают так: ℤ = {…, −2, −1, 0, 1, 2, …}.', '−8, 0 and 12 are integers; 1/2 is not. The fraction 6/3 equals the integer 2.', '−8, 0 и 12 — целые; 1/2 не целое. Дробь 6/3 равна целому числу 2.', 'Classify the value, not the notation: a fraction can represent an integer. “Natural number” conventions differ about including zero.', 'Определяй, целое ли значение, а не запись: дробь может равняться целому числу. Учебники расходятся в том, входит ли ноль в натуральные числа.'],
  ['Consecutive', 'Последовательные', 'Numbers that follow one another in a given ordered sequence, with no term skipped. Consecutive integers are whole numbers that differ by 1.', 'Числа, которые идут друг за другом в заданной последовательности, без пропуска членов. Последовательные целые числа отличаются на 1.', 'Consecutive integers can be written n, n + 1, n + 2; consecutive even integers as 2n, 2n + 2.', 'Последовательные целые записывают как n, n + 1, n + 2, а последовательные чётные — как 2n, 2n + 2.', 'Consecutive even integers differ by 2, so name the sequence you mean.', 'Последовательные чётные числа отличаются на 2, поэтому назови последовательность, о которой идёт речь.'],
]);
group(['coordinates'], [
  ['Coordinate', 'Координата', 'A number that gives the position of a point along one axis. A point on a plane has two coordinates: the x-coordinate and the y-coordinate.', 'Число, которое задаёт положение точки вдоль одной оси. У точки на плоскости две координаты: координата x и координата y.', 'A(−2, 5) lies 2 units left and 5 units up from the origin.', 'Точка A(−2; 5) расположена на 2 единицы левее и на 5 единиц выше начала координат.', 'The point is an ordered pair; each coordinate is one number. (−2, 5) and (5, −2) are different points.', 'Точку задаёт упорядоченная пара, а каждая координата — одно число. (−2; 5) и (5; −2) — разные точки.', 'coordinate'],
  ['Midpoint', 'Середина отрезка', 'The point on a segment at equal distances from its two endpoints. Its coordinates are the averages of the endpoint coordinates.', 'Точка отрезка, равноудалённая от его концов. Её координаты — средние арифметические соответствующих координат концов.', 'For P(3, −2) and Q(7, 6), M = ((3 + 7)/2, (−2 + 6)/2) = (5, 2).', 'Для P(3; −2) и Q(7; 6): M = ((3 + 7)/2, (−2 + 6)/2) = (5; 2).', 'Do not average all four numbers at once: the result is one number, not a midpoint.', 'Не усредняй все четыре числа сразу: получится одно число, а не середина отрезка.', 'coordinate'],
  ['Distance formula', 'Формула расстояния', 'The distance d between two points is d = √((Δx)² + (Δy)²), where Δx and Δy are the changes in x and y measured in the same unit. The formula comes from the Pythagorean theorem.', 'Расстояние d между двумя точками: d = √((Δx)² + (Δy)²), где Δx и Δy — изменения координат x и y в одних единицах длины. Формула выведена из теоремы Пифагора.', 'From P(1, 2) to Q(4, 6): Δx = 3, Δy = 4, so d = √(9 + 16) = √25 = 5 units.', 'Для P(1; 2) и Q(4; 6): Δx = 3, Δy = 4, поэтому d = √(9 + 16) = √25 = 5 единиц.', 'Do not add Δx and Δy: 3 + 4 = 7 is the length of a route along the grid, not the straight-line distance 5.', 'Не складывай Δx и Δy: сумма 3 + 4 = 7 — это длина пути по клеткам, а не прямое расстояние 5.', 'coordinate'],
  ['Intercept', 'Пересечение с осью', 'A point where a graph meets a coordinate axis. At an x-intercept y = 0; at a y-intercept x = 0.', 'Точка, в которой график пересекает координатную ось. У точки пересечения с осью x значение y равно 0, у точки пересечения с осью y значение x равно 0.', 'For y = 2x − 6: setting x = 0 gives (0, −6); setting y = 0 gives (3, 0).', 'Для y = 2x − 6: при x = 0 получаем (0; −6); при y = 0 — (3; 0).', 'Do not confuse the point with its coordinate: in y = 2x − 6 the y-intercept is −6, and the point where the line crosses the y-axis is (0, −6).', 'Не путай точку и её координату: в y = 2x − 6 пересечение с осью y равно −6, а точка пересечения — (0; −6).'],
]);
group(['lines'], [
  ['Gradient / slope', 'Угловой коэффициент; наклон', 'The gradient m is the rise (change in y) divided by the run (change in x) between two points on a non-vertical line. The ratio is the same for any two points on the line.', 'Угловой коэффициент m (в российской школе часто пишут k) — отношение изменения y к изменению x между двумя точками невертикальной прямой: m = Δy/Δx. Для любых двух точек этой прямой отношение одно и то же.', 'From P(−1, 4) to Q(3, −2): m = (−2 − 4)/(3 − (−1)) = −6/4 = −3/2.', 'Для P(−1; 4) и Q(3; −2): m = (−2 − 4)/(3 − (−1)) = −6/4 = −3/2.', 'Slope is a ratio, not an angle or distance.', 'Угловой коэффициент — отношение, а не угол и не расстояние.', 'coordinate'],
  ['Undefined gradient', 'Неопределённый угловой коэффициент', 'A vertical line has no gradient, because any two of its points have Δx = 0. Then Δy/Δx has 0 in the denominator, so it is undefined.', 'У вертикальной прямой нет углового коэффициента: у любых двух её точек Δx = 0. Тогда в знаменателе Δy/Δx стоит 0, и отношение не определено.', 'For (4, 1) and (4, 7): Δy = 6 and Δx = 0, so Δy/Δx = 6/0 is undefined; the line is x = 4.', 'Для (4; 1) и (4; 7): Δy = 6 и Δx = 0, поэтому Δy/Δx = 6/0 не определено; прямая имеет вид x = 4.', 'x = 4 is a vertical line and y = 4 is horizontal: on a vertical line only x is fixed.', 'x = 4 — вертикальная прямая, а y = 4 — горизонтальная: у вертикальной прямой постоянна только координата x.'],
  ['Perpendicular lines', 'Перпендикулярные прямые', 'Two lines in a plane that intersect at an angle of 90°.', 'Две прямые на плоскости, которые пересекаются под углом 90°.', 'The lines y = 4x + 1 and y = −(1/4)x + 3 have gradients 4 and −1/4. Multiplying the gradients gives 4 × (−1/4) = −1, so the lines are perpendicular.', 'Прямые y = 4x + 1 и y = −(1/4)x + 3 имеют угловые коэффициенты 4 и −1/4. Их произведение равно 4 × (−1/4) = −1, значит, прямые перпендикулярны.', 'A 90° angle can look distorted in a sketch if the x- and y-axes have different scales. Check perpendicularity with the gradients, not by eye.', 'Угол в 90° на рисунке может выглядеть искажённым, если масштабы осей x и y разные. Проверяй перпендикулярность по угловым коэффициентам, а не на глаз.'],
  ['Negative reciprocal', 'Число, противоположное обратному', 'For a non-zero number m, the value −1/m, obtained by taking its reciprocal and changing the sign.', 'Для k ≠ 0 это число −1/k: берут обратное число и меняют его знак.', 'For m = −2/3, the negative reciprocal is −1/m = −1/(−2/3) = 3/2. Check: (−2/3) × (3/2) = −1.', 'Для k = −2/3 число, противоположное обратному, равно −1/k = −1/(−2/3) = 3/2. Проверка: (−2/3) × (3/2) = −1.', 'The reciprocal of 5 is 1/5, but its negative reciprocal is −1/5. Only the negative reciprocal gives −1 when multiplied by 5.', 'Число, обратное 5, равно 1/5, а число, противоположное обратному, — −1/5. Только оно при умножении на 5 даёт −1.'],
  ['Parallel lines', 'Параллельные прямые', 'Distinct lines in the same plane that have no common point, however far extended.', 'Различные прямые одной плоскости, не имеющие общей точки при любом продолжении.', 'The lines y = 3x + 1 and y = 3x − 5 have the same gradient, 3, but different y-intercepts, so they are parallel.', 'У прямых y = 3x + 1 и y = 3x − 5 одинаковый угловой коэффициент 3, но разные точки пересечения с осью y. Значит, они параллельны.', 'Lines with equal gradients and equal y-intercepts are one and the same line, not two different lines that are parallel. Two different vertical lines, such as x = 1 and x = 4, are also parallel.', 'Прямые с равными угловыми коэффициентами и равными точками пересечения с осью y — это одна и та же прямая, а не две разные параллельные прямые. Две разные вертикальные прямые, например x = 1 и x = 4, тоже параллельны.'],
]);
group(['systems', 'ruSystems'], [
  ['Simultaneous equations', 'Система уравнений', 'Two or more equations with the same variables, which must be solved together. A solution gives values for the variables that make every equation in the system true.', 'Два или больше уравнений с одними и теми же переменными, которые решают вместе. Решение системы — набор значений переменных, при котором верно каждое уравнение.', 'x = 5 and y = 5 satisfy x + y = 10, but not x − y = 4, since 5 − 5 = 0. The solution of the system is x = 7 and y = 3, which satisfies both.', 'Пара x = 5 и y = 5 удовлетворяет уравнению x + y = 10, но не удовлетворяет уравнению x − y = 4, так как 5 − 5 = 0. Решение системы: x = 7 и y = 3, оно удовлетворяет обоим уравнениям.', 'Solving only one equation does not solve the system. One equation, such as x + y = 10, has infinitely many pairs that satisfy it, including (0, 10) and (1, 9).', 'Решить одно уравнение — ещё не значит решить систему. Одному уравнению, например x + y = 10, удовлетворяют бесконечно много пар, в том числе (0; 10) и (1; 9).'],
  ['Elimination method', 'Метод сложения', 'Add or subtract the equations, after multiplying them by suitable numbers, so that one variable cancels out. The result is an equation in one variable.', 'Уравнения складывают или вычитают, предварительно умножив их на подходящие числа, чтобы одна переменная исключилась. Получается уравнение с одной переменной.', 'Add x + y = 7 to x − y = 1: 2x = 8, so x = 4. Then use an original equation to find y = 3.', 'Складываем x + y = 7 и x − y = 1: 2x = 8, значит x = 4. Затем по исходному уравнению находим y = 3.', 'As they stand, a variable cancels only if its coefficients are opposite (add) or equal (subtract). Adding 2x + 3y = 17 and 3x − 2y = 6 gives 5x + y = 23, which still has two variables.', 'В исходном виде переменная исчезает, только если её коэффициенты противоположны (складываем) или равны (вычитаем). Сложив 2x + 3y = 17 и 3x − 2y = 6, получим 5x + y = 23: в этом уравнении остались две переменные.'],
  ['Substitution method', 'Метод подстановки', 'Solve one equation for one variable, substitute that expression into the other equation, then find and check the other variable.', 'Выразить одну переменную из одного уравнения, подставить полученное выражение в другое уравнение, затем найти и проверить вторую переменную.', 'If y = 7 − x and x − y = 1, then x − (7 − x) = 1, so x = 4 and y = 3.', 'Если y = 7 − x и x − y = 1, то x − (7 − x) = 1, откуда x = 4 и y = 3.', 'Put the whole expression in brackets. The minus sign in front changes both terms inside: x − (7 − x) = x − 7 + x, not x − 7 − x.', 'Выражение нужно брать в скобки. Минус перед скобками меняет знаки у обоих слагаемых внутри: x − (7 − x) = x − 7 + x, а не x − 7 − x.'],
  ['Intersection point', 'Точка пересечения (графиков)', 'The point where two graphs meet. Its coordinates satisfy both equations, so it is a solution of the system.', 'Точка, в которой пересекаются два графика. Её координаты удовлетворяют обоим уравнениям, поэтому это решение системы.', 'The lines y = x − 1 and y = 3 meet at (4, 3), which solves the system.', 'Прямые y = x − 1 и y = 3 пересекаются в точке (4; 3): это решение системы.', 'Parallel lines have no common point, so the system has no solution.', 'Параллельные прямые не имеют общей точки, поэтому система не имеет решений.'],
]);
group(['setOperations', 'ruSets'], [
  ['Intersection', 'Пересечение множеств', 'The intersection A ∩ B is the set of elements that belong to both sets. For two graphs, it is the set of points that lie on both graphs.', 'Пересечение A ∩ B — это множество элементов, которые принадлежат обоим множествам. Для двух графиков это множество точек, лежащих на обоих графиках.', 'If A = {1, 3, 5} and B = {3, 4}, then A ∩ B = {3}. The lines y = x − 1 and y = 3 meet at (4, 3), so the intersection of their graphs is {(4, 3)}.', 'Если A = {1, 3, 5} и B = {3, 4}, то A ∩ B = {3}. Прямые y = x − 1 и y = 3 пересекаются в точке (4; 3), поэтому пересечение их графиков — {(4; 3)}.', 'Do not swap the symbols. A ∩ B has no more elements than either set, but A ∪ B has no fewer than either set.', 'Не перепутай знаки. У A ∩ B не больше элементов, чем у каждого из множеств, а у A ∪ B — не меньше, чем у каждого из них.', 'venn'],
  ['Union', 'Объединение множеств', 'The union A ∪ B is the set of all elements that belong to at least one of the given sets.', 'Объединение A ∪ B — это множество всех элементов, которые принадлежат хотя бы одному из данных множеств.', 'For A = {1, 3, 5}, B = {3, 4}, A ∪ B = {1, 3, 4, 5}.', 'Для A = {1, 3, 5}, B = {3, 4} получаем A ∪ B = {1, 3, 4, 5}.', '“Or” here includes “both”: an element in both sets still belongs to A ∪ B.', 'Здесь «или» включает и случай «оба»: элемент, который есть в обоих множествах, всё равно входит в A ∪ B.', 'venn'],
  ['Complement', 'Дополнение множества', 'Relative to a specified universal set U, the complement of A, written A′, contains every element of U that is not in A.', 'Относительно заданного универсального множества U дополнение A, обозначаемое A′, содержит все элементы U, которых нет в A.', 'If U = {1, 2, 3, 4} and A = {1, 4}, then A′ = {2, 3}.', 'Если U = {1, 2, 3, 4}, A = {1, 4}, то A′ = {2, 3}.', 'A′ is not the same as B. For U = {1, 2, 3, 4, 5}, A = {1, 2} and B = {2, 3}, the set A′ = {3, 4, 5} also contains 4 and 5, which are in neither set.', 'A′ — не то же самое, что B. Для U = {1, 2, 3, 4, 5}, A = {1, 2} и B = {2, 3} множество A′ = {3, 4, 5}. Оно содержит ещё 4 и 5, которых нет ни в A, ни в B.', 'venn'],
  ['Disjoint sets', 'Непересекающиеся множества', 'Two sets are disjoint when they have no elements in common. Then their intersection is the empty set.', 'Два множества называют непересекающимися (disjoint), если у них нет общих элементов. Тогда их пересечение — пустое множество.', '{1, 3} and {2, 4} are disjoint because no number appears in both.', '{1, 3} и {2, 4} не пересекаются: ни одно число не входит в оба множества.', 'Different sets need not be disjoint: {1, 2} and {2, 3} differ but share 2.', 'Разные множества могут иметь общие элементы: {1, 2} и {2, 3} различны, но оба содержат 2.'],
]);
group(['sets'], [
  ['Set', 'Множество', 'A set is a collection of distinct objects, and for each object it is clear whether it belongs to the set or not.', 'Множество — это совокупность различных объектов, о каждом из которых можно точно сказать, входит ли он в это множество.', 'A = {2, 4, 6}; listing {6, 2, 4, 2} gives the same set.', 'A = {2, 4, 6}; запись {6, 2, 4, 2} задаёт то же множество.', 'Order and repetitions do not change a set. They can change a list or sequence.', 'Порядок и повторения не меняют множество, но могут менять список или последовательность.'],
  ['Element (member)', 'Элемент множества', 'An element is an individual object that belongs to a set. The notation a ∈ A means that a is an element of A.', 'Элемент — это отдельный объект, который входит в множество. Запись a ∈ A значит, что a — элемент A.', 'If A = {2, 4, 6}, then 4 ∈ A and 5 ∉ A.', 'Если A = {2, 4, 6}, то 4 ∈ A и 5 ∉ A.', 'The number 4 is an element of A, but the set {4} is a subset of A: they are different objects.', 'Число 4 — элемент A, а множество {4} — подмножество A: это разные объекты.'],
  ['Universal set', 'Универсальное множество', 'The universal set U contains all the elements under consideration in a problem. Every other set in that problem is a subset of U.', 'Универсальное множество U содержит все элементы, которые рассматриваются в задаче. Любое другое множество этой задачи — подмножество (subset) U.', 'For one roll of a standard die, let U = {1, 2, 3, 4, 5, 6}. The set of even outcomes, {2, 4, 6}, is a subset of U.', 'Для одного броска обычного кубика пусть U = {1, 2, 3, 4, 5, 6}. Множество чётных результатов {2, 4, 6} — подмножество U.', 'U is not the set of everything. In a dice problem, 7 is not in U, so 7 cannot be an outcome.', 'U — не «всё на свете». В задаче про кубик число 7 не входит в U, поэтому 7 не может выпасть.', 'venn'],
  ['Empty set', 'Пустое множество', 'The empty set is the set that contains no elements. It is written ∅ or { }.', 'Пустое множество (empty set) — это множество, которое не содержит ни одного элемента. Обозначается ∅ или { }.', 'The set of integers strictly between 2 and 3 is ∅, so n(∅) = 0.', 'Множество целых чисел строго между 2 и 3 — это ∅, поэтому n(∅) = 0.', '∅ is not the same as {0}. The set {0} has one element, the number 0; ∅ has no elements at all.', '∅ — не то же самое, что {0}. В множестве {0} один элемент — число 0, а в ∅ нет ни одного элемента.'],
  ['Cardinality', 'Мощность множества', 'For a finite set, the cardinality is the number of distinct elements it contains. It is written n(A).', 'Для конечного множества мощность (cardinality) — это число его различных элементов. Обозначается n(A).', 'For A = {2, 2, 5, 8}, the number 2 is written twice but counted once, so n(A) = 3.', 'Для A = {2, 2, 5, 8} число 2 записано дважды, но считается один раз, поэтому n(A) = 3.', 'n(A) is a number, while A is a set. Write n(A) = 3, not A = 3.', 'n(A) — число, а A — множество. Пиши n(A) = 3, а не A = 3.'],
]);
group(['subsets'], [
  ['Subset', 'Подмножество', 'Set A is a subset of set B if every element of A is also an element of B. It is written A ⊆ B.', 'Множество A — подмножество множества B, если каждый элемент A входит в B. Обозначается A ⊆ B.', '{2, 4} ⊆ {2, 4, 6}. Every set is a subset of itself.', '{2, 4} ⊆ {2, 4, 6}. Каждое множество — подмножество самого себя.', 'In A ⊆ B, the set A lies inside B. So {1, 3} ⊆ {1, 2, 3} is true, but {1, 2, 3} ⊆ {1, 3} is false.', 'В записи A ⊆ B множество A лежит внутри B. Поэтому {1, 3} ⊆ {1, 2, 3} — верно, а {1, 2, 3} ⊆ {1, 3} — неверно.'],
]);

group(['functions'], [
  ['Function', 'Функция', 'A function is a relation in which each input in the domain gives exactly one output.', 'Функция (function) — это соответствие, в котором каждому аргументу (input) из области определения соответствует ровно одно значение функции (output).', 'For the rule y = 4x, the input x = 2 gives exactly one output, y = 8.', 'Для правила y = 4x при x = 2 получаем одно значение: y = 8.', 'The pairs (2, 3) and (2, −3) do not define a function, because the input 2 gives two different outputs.', 'Пары (2; 3) и (2; −3) не задают функцию: при аргументе 2 получаются два разных значения.', 'function'],
  ['Mapping', 'Отображение', 'A mapping pairs each element of one set with an element of another set. If the mapping is a function, each element of the first set is paired with exactly one element of the second set.', 'Отображение (mapping) — это правило, которое сопоставляет элементы одного множества элементам другого. Если отображение задаёт функцию, каждому элементу первого множества соответствует ровно один элемент второго.', 'The rule x ↦ 2x + 1 sends 0 ↦ 1 and 3 ↦ 7.', 'Правило x ↦ 2x + 1 даёт 0 ↦ 1 и 3 ↦ 7.', 'A mapping diagram must show every element of a finite domain. Drawing only one or two arrows does not show the whole mapping.', 'Диаграмма отображения должна показывать все элементы конечной области определения. Одной или двух стрелок недостаточно, чтобы показать всё отображение.', 'function'],
  ['Vertical line test', 'Тест вертикальной прямой', 'The vertical line test: if no vertical line crosses a graph at more than one point, the graph shows y as a function of x.', 'Тест вертикальной прямой (vertical line test): если ни одна вертикальная прямая не пересекает график более чем в одной точке, график задаёт y как функцию (function) от x.', 'The circle x² + y² = 1 fails the test: the line x = 0 meets it at (0, 1) and (0, −1).', 'Окружность x² + y² = 1 не проходит тест: прямая x = 0 пересекает её в точках (0; 1) и (0; −1).', 'A vertical line that misses the graph does not break the test. It only means that this x is outside the domain.', 'Вертикальная прямая, которая не пересекает график, тест не нарушает. Это значит только, что такого x нет в области определения.'],
  ['One-to-one and many-to-one', 'Отображения «один к одному» и «много к одному»', 'In a one-to-one mapping, different inputs always give different outputs. In a many-to-one mapping, at least two different inputs give the same output.', 'При отображении «один к одному» (one-to-one) разные аргументы всегда дают разные значения функции. При отображении «много к одному» хотя бы два разных аргумента дают одно и то же значение.', 'On the real numbers, y = x³ is one-to-one, but y = x² is many-to-one, since (−3)² = 3² = 9.', 'На действительных числах y = x³ — «один к одному», а y = x² — «много к одному», так как (−3)² = 3² = 9.', 'The domain can change the type: y = x² with x ≥ 0 is one-to-one, because each output y ≥ 0 comes from only one non-negative x.', 'Область определения может менять тип. Например, y = x² при x ≥ 0 — уже «один к одному»: каждое значение y ≥ 0 получается из одного неотрицательного x.', 'function'],
]);
group(['domain', 'ruDomain'], [
  ['Domain', 'Область определения', 'The domain is the set of input values for which the function is defined. If no domain is stated, use all real numbers (ℝ) for which the rule makes sense, for example all x except those that make a denominator zero.', 'Область определения (domain) — это множество аргументов (input), при которых функция определена. Если область определения не задана, берут все действительные числа (ℝ), для которых правило имеет смысл, например все x, кроме тех, при которых знаменатель равен нулю.', 'For f(x) = √(x − 2), the radicand must be non-negative: x − 2 ≥ 0, so the domain is [2, ∞).', 'Для f(x) = √(x − 2) подкоренное выражение (radicand) должно быть неотрицательным: x − 2 ≥ 0. Значит, область определения — [2; ∞).', 'A formula can allow inputs that a real situation does not. If t is time, the model needs t ≥ 0, even if the formula also works for negative t.', 'Формула может допускать аргументы, которых нет в реальной ситуации. Если t — время, модель требует t ≥ 0, даже если формула работает и при отрицательных t.', 'function'],
  ['Range', 'Область значений', 'The range is the set of all output values that a function actually takes on as its input runs through the domain.', 'Область значений (range) — это все значения функции (output), которые она действительно принимает на своей области определения.', 'For g(x) = 5 − 2x on 0 ≤ x ≤ 2, g(0) = 5 and g(2) = 1, so the range is 1 ≤ y ≤ 5.', 'Для g(x) = 5 − 2x при 0 ≤ x ≤ 2 получаем g(0) = 5 и g(2) = 1. Значит, область значений — 1 ≤ y ≤ 5.', 'Changing the domain can change the range. For the same g(x) = 5 − 2x on 0 ≤ x ≤ 1, the range is 3 ≤ y ≤ 5.', 'Изменение области определения может изменить область значений. Для той же функции g(x) = 5 − 2x при 0 ≤ x ≤ 1 получаем 3 ≤ y ≤ 5.', 'function'],
]);
group(['quadratics', 'parabola'], [
  ['Quadratic function', 'Квадратичная функция', 'A quadratic function is a polynomial function of degree 2: its highest power of x is 2. Its rule is y = ax² + bx + c, where a, b and c are real numbers and a ≠ 0.', 'Квадратичная функция — это функция, заданная многочленом (polynomial) второй степени: наибольшая степень x в нём равна 2. Её правило — y = ax² + bx + c, где a, b и c — действительные числа, a ≠ 0.', 'y = 3x² − 2x + 5 is a quadratic function, because its highest power of x is 2. Here a = 3, b = −2 and c = 5.', 'y = 3x² − 2x + 5 — квадратичная функция, потому что наибольшая степень x равна 2. Здесь a = 3, b = −2 и c = 5.', 'If a = 0, the x² term disappears: y = 3x + 1 is linear, and its graph is a straight line. Do not confuse the function y = ax² + bx + c with the equation ax² + bx + c = 0.', 'Если a = 0, член с x² исчезает: например, y = 3x + 1 — линейная функция, и её график — прямая. Не путай функцию y = ax² + bx + c с уравнением ax² + bx + c = 0.'],
  ['Parabola', 'Парабола', 'A parabola is the smooth curve that is the graph of a quadratic function. It looks like a U or an upside-down U, and it has exactly one turning point, the vertex.', 'Парабола (parabola) — гладкая кривая, которая служит графиком квадратичной функции. Она похожа на U или на перевёрнутое U и имеет ровно одну точку поворота — вершину (vertex).', 'For y = x², both x = −2 and x = 2 give y = 4, so the parabola is symmetrical about the y-axis.', 'Для y = x² значения x = −2 и x = 2 дают одно и то же y = 4, поэтому парабола симметрична относительно оси y.', 'Not every U-shaped curve is a parabola. The graph of y = x⁴ is U-shaped, but it is not a parabola, because its highest power of x is 4.', 'Не всякая U-образная кривая — парабола. График y = x⁴ похож на U, но это не парабола: наибольшая степень x в нём равна 4.', 'quadratic'],
  ['Vertex (turning point)', 'Вершина параболы (точка поворота)', 'The vertex is the turning point of a parabola. It is the point where the gradient changes from positive to negative, or from negative to positive.', 'Вершина (vertex) — точка поворота параболы. В ней угловой коэффициент (gradient) графика меняет знак: с положительного на отрицательный или наоборот.', 'For y = 3(x − 2)² − 5, the vertex is (2, −5).', 'У y = 3(x − 2)² − 5 вершина — (2; −5).', 'A vertex is a point (h, k), not just the y-value k. Writing \'vertex = −5\' is wrong, because the vertex of y = 3(x − 2)² − 5 is (2, −5).', 'Вершина — это точка (h; k), а не только число k. Запись «вершина = −5» неверна: вершина — (2; −5).', 'quadratic'],
  ['Axis of symmetry', 'Ось симметрии', 'The axis of symmetry is the vertical line through the vertex. The two halves of the parabola are mirror images across this line. For y = ax² + bx + c, its equation is x = −b/(2a), where a and b are the coefficients.', 'Ось симметрии (axis of symmetry) — вертикальная прямая, проходящая через вершину. Две половины параболы — зеркальные отражения друг друга относительно этой прямой. Для y = ax² + bx + c её уравнение: x = −b/(2a), где a и b — коэффициенты.', 'For y = x² + 4x + 1, the axis is x = −4/(2 × 1) = −2.', 'Для y = x² + 4x + 1 ось симметрии: x = −4/(2 × 1) = −2.', 'The axis is a line, so write it as an equation, such as x = −2. Do not write the point (−2, 0) or the number −2 alone.', 'Ось — это прямая, поэтому записывай её уравнением, например x = −2. Не пиши точку (−2; 0) и не одно число −2.', 'quadratic'],
]);
group(['zeros'], [
  ['Zero (root)', 'Нуль функции (корень)', 'A zero of a function is an x-value where y = 0. It is also a root of the equation f(x) = 0.', 'Нуль функции (zero) — значение x, при котором y = 0. Это также корень (root) уравнения f(x) = 0.', 'f(x) = x² − 9 = (x − 3)(x + 3) has zeros 3 and −3, so the graph meets the x-axis at (3, 0) and (−3, 0).', 'У функции f(x) = x² − 9 = (x − 3)(x + 3) нули 3 и −3. Поэтому график пересекает ось x в точках (3; 0) и (−3; 0).', 'Not every quadratic has two zeros. For y = (x + 1)², the graph meets the x-axis only at its vertex, (−1, 0), so there is one repeated zero.', 'Не у каждой квадратичной функции два нуля. У y = (x + 1)² график касается оси x только в вершине (−1; 0). Значит, здесь один кратный нуль.', 'quadratic'],
]);
group(['transformations'], [
  ['Translation / reflection / stretch', 'Сдвиг / отражение / растяжение', 'A translation moves every point the same distance in the same direction. A reflection flips the graph over a line, such as the x-axis. A vertical stretch multiplies every y-value by the same scale factor.', 'Сдвиг (translation) переносит каждую точку на одно и то же расстояние в одном направлении. Отражение (reflection) — зеркальное отображение графика относительно прямой, например оси x. Растяжение по вертикали (vertical stretch) умножает каждое значение y на один и тот же коэффициент растяжения.', 'From y = x² to y = −2(x − 3)² + 1: translate 3 units right, stretch vertically by 2, reflect in the x-axis, then translate 1 unit up.', 'Чтобы получить y = −2(x − 3)² + 1 из y = x², сдвинь график вправо на 3. Затем растяни его по вертикали в 2 раза, отрази относительно оси x и сдвинь вверх на 1.', 'Adding 2 to y moves the graph 2 units up, but multiplying y by 2 stretches it. So y = x² + 2 is a translation of y = x², but y = 2x² is not.', 'Прибавление 2 к y сдвигает график на 2 единицы вверх, а умножение y на 2 растягивает его. Поэтому y = x² + 2 — это сдвиг графика y = x², а y = 2x² — уже не сдвиг.'],
]);
group(['quadraticEquations'], [
  ['Factorise', 'Разложить на множители', 'Rewrite an expression as factors multiplied together, so that the two forms are equal for every value of the variable.', 'Разложение на множители (factorising) — это запись выражения в виде произведения множителей. Оно равно исходному выражению при любых значениях переменной.', 'x² + x − 6 = (x + 3)(x − 2). Check by expanding: (x + 3)(x − 2) = x² − 2x + 3x − 6 = x² + x − 6.', 'x² + x − 6 = (x + 3)(x − 2). Проверь, раскрыв скобки (expand): (x + 3)(x − 2) = x² − 2x + 3x − 6 = x² + x − 6.', 'Factorising does not solve an equation by itself. The expression (x + 3)(x − 2) is not 0 for every x, so only the equation (x + 3)(x − 2) = 0 has solutions.', 'Разложение на множители само по себе не решает уравнение. Выражение (x + 3)(x − 2) не равно нулю при всех x, поэтому корни есть только у уравнения (x + 3)(x − 2) = 0.'],
  ['Zero-product property', 'Свойство нулевого произведения', 'This is the zero-product property: if two or more numbers are multiplied together and the result is zero, then at least one of them is zero.', 'Свойство нулевого произведения: если произведение двух или нескольких чисел равно нулю, то хотя бы одно из этих чисел равно нулю.', '(x + 3)(x − 2) = 0, so x + 3 = 0 or x − 2 = 0. Hence x = −3 or x = 2.', '(x + 3)(x − 2) = 0, значит, x + 3 = 0 или x − 2 = 0. Отсюда x = −3 или x = 2.', 'The law works only when the right side is 0. From ab = 6 you cannot conclude that a = 6 or b = 6.', 'Свойство работает, только если правая часть равна 0. Из ab = 6 нельзя сделать вывод, что a = 6 или b = 6.'],
  ['Completing the square', 'Выделение полного квадрата', 'Completing the square means writing a quadratic expression in the form a(x + p)² + q, where p and q are numbers.', 'Выделение полного квадрата (completing the square) — это запись квадратного выражения (quadratic expression) в виде a(x + p)² + q, где p и q — числа.', 'x² + 6x + 5 = (x + 3)² − 9 + 5 = (x + 3)² − 4.', 'x² + 6x + 5 = (x + 3)² − 9 + 5 = (x + 3)² − 4.', 'Adding a square changes the value unless you subtract it again. If a ≠ 1, first take a out of the x² and x terms. Then the x² term has coefficient 1: 2x² + 8x = 2(x² + 4x).', 'Если добавить квадрат и не вычесть его, значение изменится. Если a ≠ 1, сначала вынеси a за скобки из членов с x² и x. Тогда коэффициент при x² станет равен 1: 2x² + 8x = 2(x² + 4x).'],
  ['Discriminant', 'Дискриминант', 'For ax² + bx + c = 0 with a ≠ 0, the discriminant is Δ = b² − 4ac.', 'Для уравнения ax² + bx + c = 0 (a ≠ 0) дискриминант (discriminant) — это D = b² − 4ac. В английских учебниках его обозначают Δ.', 'For x² − 5x + 6 = 0: a = 1, b = −5, c = 6, so Δ = (−5)² − 4 × 1 × 6 = 25 − 24 = 1 > 0. There are two real solutions: x = 2 and x = 3.', 'Для x² − 5x + 6 = 0 имеем a = 1, b = −5, c = 6. Тогда D = (−5)² − 4 × 1 × 6 = 25 − 24 = 1 > 0. Значит, есть два действительных корня: x = 2 и x = 3.', 'The sign of Δ decides how many real solutions there are.\n\nIf Δ > 0, there are two distinct solutions.\n\nIf Δ = 0, the equation has one real solution, counted twice (the two solutions are equal).\n\nIf Δ < 0, there are no real solutions.', 'Знак D показывает, сколько действительных корней у уравнения.\n\nПри D > 0 два различных корня.\n\nПри D = 0 уравнение имеет один действительный корень, который считают двойным (два корня совпадают).\n\nПри D < 0 действительных корней нет.'],
]);
group(['sequences'], [
  ['Term (nth term)', 'Член последовательности, или n-й член', 'A sequence is an ordered list of numbers, and each number in it is called a term. The nth term, uₙ, is the term in position n: u₁ is the first term and u₂ is the second.', 'Последовательность (sequence) — упорядоченный список чисел. Каждое число в нём называют членом. Член с номером n обозначают uₙ: u₁ — первый член, u₂ — второй и так далее.', 'For uₙ = 4n − 1, n ≥ 1: u₁ = 3, u₂ = 7 and u₅ = 19.', 'Для uₙ = 4n − 1, n ≥ 1: u₁ = 3, u₂ = 7 и u₅ = 19.', 'Do not write u₅ = 5. The index 5 only gives the position, and the value comes from the formula: u₅ = 4 × 5 − 1 = 19. A term of an expression, such as 5x in 5x − 2y + 8, is a different idea.', 'Не пиши u₅ = 5. Номер 5 показывает только место, а значение находят по формуле: u₅ = 4 × 5 − 1 = 19. Слагаемое выражения (term), например 5x в 5x − 2y + 8, — это другое понятие, а не член последовательности.'],
  ['Explicit formula (position-to-term rule)', 'Явная формула', 'An explicit formula gives the nth term directly from its position number n. You do not need to calculate the earlier terms first.', 'Явная формула (explicit formula) выражает n-й член через его номер n. Вычислять предыдущие члены не нужно.', 'For uₙ = 2n + 5 (n ≥ 1), the 100th term is u₁₀₀ = 2 × 100 + 5 = 205, so you do not need to write out the first 99 terms.', 'Для uₙ = 2n + 5 (n ≥ 1) сотый член равен u₁₀₀ = 2 × 100 + 5 = 205, поэтому первые 99 членов выписывать не нужно.', 'Check where the numbering starts. If the first term is u₁, then 7, 9, 11, … is given by uₙ = 2n + 5. If you start from u₀ instead, the same list is given by uₙ = 2n + 7.', 'Проверь, с какого номера начинается нумерация. Если первый член — u₁, то для 7, 9, 11, … получаем uₙ = 2n + 5. Если начать с u₀, та же последовательность описывается формулой uₙ = 2n + 7.'],
  ['Recursive formula (term-to-term rule)', 'Рекуррентная формула', 'A recursive formula finds each term from the term before it. To start the sequence, you also need the first term u₁.', 'Рекуррентная формула (recursive formula) находит каждый член по предыдущему. Чтобы задать последовательность, нужен ещё первый член u₁.', 'For u₁ = 4 and uₙ₊₁ = uₙ + 5: u₂ = 4 + 5 = 9, u₃ = 9 + 5 = 14 and u₄ = 14 + 5 = 19. The sequence is 4, 9, 14, 19, …', 'Для u₁ = 4 и uₙ₊₁ = uₙ + 5: u₂ = 4 + 5 = 9, u₃ = 9 + 5 = 14, u₄ = 14 + 5 = 19. Получаем последовательность 4, 9, 14, 19, …', 'Do not mix up the indices. uₙ₊₁ is the next term, uₙ is the current term and uₙ₋₁ is the one before it. The rule uₙ = uₙ + 5 is wrong, because a term cannot be equal to itself plus 5.', 'Не путай индексы: uₙ₊₁ — следующий член, uₙ — текущий, uₙ₋₁ — предыдущий. Запись uₙ = uₙ + 5 неверна: член не может быть равен самому себе плюс 5.'],
]);
group(['arithmetic'], [
  ['Arithmetic sequence (linear sequence)', 'Арифметическая прогрессия, или линейная последовательность', 'In an arithmetic sequence, each term is the previous term plus the same number d, the common difference: uₙ₊₁ = uₙ + d. Its explicit formula uₙ = u₁ + (n − 1)d is linear in n, so the sequence is also called a linear sequence.', 'В арифметической прогрессии (arithmetic sequence) каждый член получают, прибавляя к предыдущему одно и то же число d. Это число называют разностью прогрессии (common difference): uₙ₊₁ = uₙ + d. Формула uₙ = u₁ + (n − 1)d линейна относительно n, поэтому такую последовательность называют линейной.', '5, 2, −1, −4, … has d = −3 and uₙ = 5 − 3(n − 1), n ≥ 1.', '5, 2, −1, −4, … имеет d = −3 и uₙ = 5 − 3(n − 1), n ≥ 1.', 'Do not confuse the two types. In 2, 4, 6, 8 the difference between consecutive terms is always 2, so it is arithmetic. In 2, 4, 8, 16 the differences 2, 4, 8 are not equal, but the ratio is always 2, so it is geometric.', 'Не путай арифметическую и геометрическую прогрессии. В последовательности 2, 4, 6, 8 разность соседних членов всегда равна 2, значит, это арифметическая прогрессия. В последовательности 2, 4, 8, 16 разности 2, 4 и 8 не одинаковы, зато отношение соседних членов всегда равно 2: это геометрическая прогрессия.'],
]);
group(['geometric'], [
  ['Geometric sequence (geometric progression)', 'Геометрическая прогрессия', 'Extended: in a geometric sequence, each term is the previous term multiplied by the same number r, the common ratio: uₙ₊₁ = r × uₙ. The ratio is found by dividing any term by the term before it.', 'Extended: в геометрической прогрессии (geometric sequence) каждый член получают умножением предыдущего на одно и то же число r. Это число называют знаменателем прогрессии (common ratio): uₙ₊₁ = r × uₙ. Чтобы найти знаменатель, раздели любой член на предыдущий.', 'Extended: 8, −4, 2, −1, …: the common ratio is r = −4 ÷ 8 = −1/2. uₙ = u₁ × rⁿ⁻¹ = 8 × (−1/2)ⁿ⁻¹, so u₅ = 8 × (−1/2)⁴ = 8 × 1/16 = 1/2.', 'Extended: 8, −4, 2, −1, …: знаменатель прогрессии r = −4 : 8 = −1/2. uₙ = u₁ × rⁿ⁻¹ = 8 × (−1/2)ⁿ⁻¹, поэтому u₅ = 8 × (−1/2)⁴ = 8 × 1/16 = 1/2.', 'Extended: the ratio can be negative, and then the signs alternate: in 1, −2, 4, −8 the ratio is −2. A negative ratio does not make the sequence decreasing, because the absolute values 1, 2, 4, 8 grow. You can find the ratio by division only when the earlier term is not zero.', 'Extended: знаменатель прогрессии может быть отрицательным: тогда знаки членов чередуются. В прогрессии 1, −2, 4, −8 знаменатель равен −2. Отрицательный знаменатель не делает прогрессию убывающей, ведь модули членов 1, 2, 4, 8 растут. Знаменатель можно найти делением, только если предыдущий член не равен нулю.'],
]);
group(['series'], [
  ['Convergence (sum to infinity)', 'Сходимость бесконечной суммы', 'Extended: an infinite geometric sum converges when its partial sums get closer and closer to one fixed finite number, S∞. For u₁ ≠ 0, this happens only when |r| < 1, and then S∞ = u₁/(1 − r).', 'Extended: бесконечная геометрическая сумма сходится, если её частичные суммы (partial sums) приближаются к одному конечному числу S∞. При u₁ ≠ 0 это происходит только при |r| < 1, и тогда S∞ = u₁/(1 − r).', 'Extended: for 1 + 1/2 + 1/4 + …, the partial sums are S₁ = 1, S₂ = 1.5, S₃ = 1.75 and S₄ = 1.875. They approach 2, so S∞ = 2.', 'Extended: для 1 + 1/2 + 1/4 + … частичные суммы равны S₁ = 1, S₂ = 1,5, S₃ = 1,75 и S₄ = 1,875. Они стремятся к 2, поэтому S∞ = 2.', 'Extended: do not assume that a sum is finite just because it has infinitely many terms. In 1 + 1 + 1 + …, the ratio is 1, so the terms never get smaller and the sum grows without limit.', 'Extended: не считай сумму конечной только потому, что слагаемых бесконечно много. В 1 + 1 + 1 + … знаменатель равен 1, члены не уменьшаются, и сумма растёт без предела.'],
]);

group(['rightTriangles'], [
  ['Hypotenuse', 'Гипотенуза', 'The side opposite the 90° angle in a right triangle; it is longer than either of the other two sides.', 'Сторона прямоугольного треугольника, лежащая напротив угла 90°; она длиннее каждого из двух катетов.', 'With legs 3 cm and 4 cm: c² = 3² + 4² = 9 + 16 = 25, so c = √25 = 5 cm.', 'Если катеты равны 3 см и 4 см, то c² = 3² + 4² = 9 + 16 = 25, значит c = √25 = 5 см.', 'The hypotenuse lies opposite the right angle. It is never the opposite side or the adjacent side, whichever acute angle you choose.', 'Гипотенуза лежит напротив прямого угла. Она никогда не бывает ни противолежащим, ни прилежащим катетом, какой бы острый угол ты ни выбрал.', 'triangle'],
  ['Opposite / adjacent', 'Противолежащий / прилежащий катет', 'For a chosen acute angle in a right triangle, the opposite side is the leg across from that angle. The adjacent side is the leg that forms the angle together with the hypotenuse.', 'Для выбранного острого угла прямоугольного треугольника противолежащий катет — это катет, лежащий напротив этого угла. Прилежащий катет образует этот угол вместе с гипотенузой.', 'If the opposite side is 5 cm and the adjacent side is 12 cm, then tan θ is 5/12, about 0.42.', 'Если противолежащий катет равен 5 см, а прилежащий — 12 см, то tg θ = 5/12 ≈ 0,42.', 'The two legs swap roles when you change the acute angle. Label the sides again for the angle given in the question.', 'Когда ты меняешь острый угол, противолежащий и прилежащий катеты меняются местами. Заново подпиши стороны для угла, который указан в задаче.', 'triangle'],
]);
group(['cosine', 'bearing'], [
  ['Bearing', 'Азимут', 'The bearing is the direction angle, measured clockwise from north at the starting point, from 000° up to but not including 360°.', 'Азимут — это угол направления, который отсчитывают по часовой стрелке от севера в начальной точке. Значения азимута идут от 000° до 359°: 360° — то же направление, что и 000°, поэтому его не пишут.', 'Due north is 000°, due east is 090°, due south is 180° and due west is 270°.', 'Север — это 000°, восток — 090°, юг — 180°, запад — 270°.', 'Write a bearing with three figures: 037°, not 37°. The leading zero is part of the answer.', 'Записывай азимут тремя цифрами: 037°, а не 37°. Ноль в начале записи — часть ответа.'],
  ['Cosine rule (Extended)', 'Теорема косинусов (Extended)', 'In any triangle, c² = a² + b² − 2ab cos C. Here C is the angle between sides a and b, and c is the side opposite C.', 'В любом треугольнике c² = a² + b² − 2ab cos C. Здесь C — угол между сторонами a и b, а c — сторона, противолежащая углу C.', 'If a = 3 cm, b = 5 cm and C = 60°, then c² = 3² + 5² − 2 × 3 × 5 × cos 60° = 34 − 15 = 19 cm², so c = √19 ≈ 4.36 cm.', 'Если a = 3 см, b = 5 см и C = 60°, то c² = 3² + 5² − 2 × 3 × 5 × cos 60° = 34 − 15 = 19 см², поэтому c = √19 ≈ 4,36 см.', 'Check that C is opposite the side you need to find, c. If C = 90°, then cos C = 0, and the cosine rule becomes Pythagoras: c² = a² + b².', 'Проверь, что угол C лежит напротив искомой стороны c. Если C = 90°, то cos C = 0, и теорема косинусов превращается в теорему Пифагора (Pythagoras’ theorem): c² = a² + b².'],
]);
group(['inverseTrig'], [
  ['Inverse trigonometric function', 'Обратная тригонометрическая функция', 'An inverse trigonometric function finds an angle from its trigonometric ratio. For example, if sin θ = x, where x is a number from −1 to 1, then θ = sin⁻¹(x), provided θ lies between −90° and 90°. The inverse function undoes the sine.', 'Арксинус, арккосинус и арктангенс (inverse trigonometric functions) находят угол по значению синуса, косинуса или тангенса. Например, если sin θ = x, где x — число от −1 до 1, то θ = sin⁻¹(x), если θ лежит от −90° до 90°. Обратная функция отменяет действие синуса.', 'In degree mode, arcsin(1/2) = 30°. But sin θ = 1/2 for 0° ≤ θ ≤ 180° also has the solution θ = 150°.', 'В градусном режиме arcsin(1/2) = 30°. Но уравнение sin θ = 1/2 при 0° ≤ θ ≤ 180° имеет и второе решение: θ = 150°.', 'The inverse sine gives angles from −90° to 90°, and the inverse tangent gives angles strictly between −90° and 90°. The inverse cosine gives angles from 0° to 180°, so it can give an obtuse angle.', 'Арксинус даёт углы от −90° до 90°, а арктангенс — углы строго между −90° и 90°. Арккосинус даёт углы от 0° до 180°, поэтому может дать тупой угол.'],
]);
group(['sine'], [
  ['Sine rule (Extended)', 'Теорема синусов (Extended)', 'In any triangle, each side divided by the sine of its opposite angle gives the same value: a / sin A = b / sin B = c / sin C. Here a, b and c are the sides, and A, B and C are the angles opposite them.', 'В любом треугольнике каждая сторона, делённая на синус противолежащего угла, даёт одно и то же число: a / sin A = b / sin B = c / sin C. Здесь a, b и c — стороны, а A, B и C — углы, противолежащие им.', 'If a = 4 cm, A = 30° and B = 60°, then b = 4 × sin 60° / sin 30° = 4√3 ≈ 6.93 cm.', 'Если a = 4 см, A = 30° и B = 60°, то b = 4 × sin 60° / sin 30° = 4√3 ≈ 6,93 см.', 'The sine stands in the denominator, so a/sin A means a divided by sin A. To find b, multiply a by sin B and divide by sin A.', 'Синус стоит в знаменателе: a/sin A означает a, делённое на sin A. Чтобы найти b, умножь a на sin B и раздели на sin A.'],
  ['Included angle (Extended)', 'Угол между сторонами (Extended)', 'The angle formed where two specified sides of a triangle meet.', 'Угол, образованный двумя указанными сторонами треугольника в их общей вершине.', 'If sides a = 4 cm and b = 7 cm enclose C = 30°, then the area is ½ × a × b × sin C = ½ × 4 × 7 × sin 30° = 7 cm².', 'Если стороны a = 4 см и b = 7 см заключают между собой угол C = 30°, то площадь равна ½ × a × b × sin C = ½ × 4 × 7 × sin 30° = 7 см².', 'C must be the angle between a and b. If you use an angle opposite a or b, the area is wrong, because that angle does not lie between the two given sides.', 'Угол C должен лежать между сторонами a и b. Если взять угол, противолежащий стороне a или b, площадь получится неверной: он не лежит между данными сторонами.'],
]);
group(['waves'], [
  ['Amplitude (Extended)', 'Амплитуда (Extended)', 'The amplitude of a sine or cosine graph is the height from the midline to the maximum or minimum value, so it equals half the difference between the maximum and minimum values. The midline is the horizontal line at the mean (average) value of the function.', 'Амплитуда графика синуса или косинуса — это высота от средней линии до наибольшего или наименьшего значения. Она равна половине разности наибольшего и наименьшего значений. Средняя линия — горизонтальная прямая на уровне среднего значения функции.', 'For y = −3 sin x + 2, the largest value is 5 and the smallest is −1. So the midline is y = 2, and the amplitude is (5 − (−1)) / 2 = 3.', 'Для y = −3 sin x + 2 наибольшее значение равно 5, а наименьшее равно −1. Значит, средняя линия y = 2, а амплитуда равна (5 − (−1)) / 2 = 3.', 'The amplitude is never negative: for y = −3 sin x it is 3, not −3. A vertical shift moves the midline but does not change the amplitude. Tangent graphs have no amplitude, because they have no maximum or minimum value.', 'Амплитуда не бывает отрицательной: у y = −3 sin x она равна 3, а не −3. Вертикальный сдвиг меняет среднюю линию, но не амплитуду. У графика тангенса амплитуды нет: у него нет наибольшего и наименьшего значений.'],
  ['Period (Extended)', 'Период функции (Extended)', 'The period is the horizontal length of one complete cycle: f(x + T) = f(x) for every x. The fundamental period is the smallest positive T with this property.', 'Период — это горизонтальная длина одного полного цикла: f(x + T) = f(x) при любом x. Основной период (fundamental period) — наименьшее положительное T, при котором это верно.', 'For y = sin(4x) with x in degrees, one complete wave takes 360°/4 = 90°, so the fundamental period is 90°.', 'Для y = sin(4x), где x в градусах, одна полная волна занимает 360°/4 = 90°, значит, основной период равен 90°.', 'For y = sin(3x), the amplitude is 1 and the period is 120°, so the two numbers must not be swapped.', 'У y = sin(3x) амплитуда равна 1, а период равен 120°, поэтому эти числа нельзя путать.'],
]);
group(['circles'], [
  ['Chord / diameter', 'Хорда / диаметр', 'A chord is a line segment whose two ends lie on the circle. A diameter is a chord that passes through the centre.', 'Хорда (chord) — отрезок, концы которого лежат на окружности. Диаметр (diameter) — хорда, проходящая через центр.', 'A circle has radius 5 cm, so each diameter is 2 × 5 = 10 cm. A chord of 8 cm is shorter than 10 cm, so it does not pass through the centre.', 'Радиус окружности 5 см, значит, диаметр равен 2 × 5 = 10 см. Хорда 8 см короче 10 см, значит, она не проходит через центр.', 'A chord is straight, but an arc is curved along the circle. Both can join the same two points, so say which one you mean.', 'Хорда прямая, а дуга изогнута и идёт по окружности. Обе могут соединять одни и те же две точки, поэтому уточняй, о чём речь.', 'circle'],
  ['Tangent', 'Касательная к окружности', 'A tangent is a straight line that touches the circle at exactly one point.', 'Касательная (tangent) — прямая, которая касается окружности ровно в одной точке.', 'A circle with centre O and radius 6 cm has a tangent that touches it at T. If P is a point on the tangent with PT = 8 cm, then OP = √(6² + 8²) = 10 cm, because OT is perpendicular to PT.', 'Окружность с центром O и радиусом 6 см касается прямой в точке T. Если на этой прямой взята точка P и PT = 8 см, то OP = √(6² + 8²) = 10 см, потому что OT перпендикулярен PT.', 'Do not confuse this tangent with tan from trigonometry. Tan is not a line but a ratio: in a right-angled triangle, tan θ = opposite / adjacent.', 'Не путай касательную с тангенсом (tg) из тригонометрии. Тангенс острого угла — не прямая, а отношение: в прямоугольном треугольнике tg θ = противолежащий катет / прилежащий катет.'],
  ['Arc', 'Дуга окружности', 'A curved part of the circle between two of its points. Two points split the circle into a minor arc (the shorter one) and a major arc (the longer one).', 'Дуга (arc) — часть окружности между двумя её точками. Две точки делят окружность на меньшую дугу (короткую) и большую дугу (длинную).', 'For radius 10 cm and central angle 90°, the minor arc length is (90/360) × 2π × 10 = 5π ≈ 15.71 cm.', 'При радиусе 10 см и центральном угле 90° длина меньшей дуги равна (90/360) × 2π × 10 = 5π ≈ 15,71 см.', 'The degree measure of an arc equals its central angle, for example 40°.', 'Градусная мера дуги равна центральному углу, опирающемуся на неё, например 40°.', 'circle'],
  ['Sector', 'Круговой сектор', 'A sector is a region of a disc bounded by two radii and the arc that joins their outer ends.', 'Круговой сектор (sector) — часть круга, ограниченная двумя радиусами и дугой, которая соединяет их концы.', 'For r = 9 cm and θ = 120°, the area of this sector = (120/360) × π × 9² = 27π ≈ 84.82 cm².', 'При r = 9 см и θ = 120° площадь этого сектора равна (120/360) × π × 9² = 27π ≈ 84,82 см².', 'Picture a sector as a slice of pizza with its point at the centre. In a question, check which lines bound the shape you need.', 'Представь сектор как кусок пиццы с вершиной в центре. В задаче смотри, какими линиями ограничена нужная фигура.', 'circle'],
  ['Segment', 'Круговой сегмент', 'A segment is a region of a disc bounded by a chord and one of the two arcs between the chord’s ends. The smaller of the two parts is the minor segment.', 'Круговой сегмент (circular segment) — часть круга, ограниченная хордой и одной из двух дуг между концами хорды. Меньшая из двух частей — меньший круговой сегмент.', 'For r = 4 cm and minor central angle 90°, the area of this sector is 4π cm². The triangle, which is right-angled with legs 4 cm, has area 8 cm². So segment area = 4π − 8 ≈ 4.57 cm².', 'При r = 4 см и меньшем центральном угле 90° площадь этого сектора равна 4π см². Площадь треугольника (прямоугольного, с катетами 4 см) равна 8 см². Значит, площадь кругового сегмента = 4π − 8 ≈ 4,57 см².', 'Do not confuse a circle segment with a line segment, which is a straight piece of line between two points. Look at the context to tell which one is meant.', 'Не путай круговой сегмент с отрезком прямой (line segment): это два разных понятия. Смотри на контекст, чтобы понять, о чём речь.', 'circle'],
  ['Cyclic quadrilateral', 'Вписанный четырёхугольник', 'A quadrilateral whose four vertices all lie on a single circle.', 'Четырёхугольник, все четыре вершины которого лежат на одной окружности.', 'In quadrilateral ABCD, whose four corners lie on one circle, angle A is 75°. Opposite angles add up to 180°, so angle C = 180° − 75° = 105°.', 'Во вписанном четырёхугольнике ABCD угол A равен 75°. Противоположные углы в сумме дают 180°, поэтому угол C = 180° − 75° = 105°.', 'Adjacent angles, such as A and B, do not have to add up to 180°.', 'Соседние углы (adjacent), например A и B, не обязаны давать в сумме 180°.'],
]);
group(['rationalExpressions', 'ruDomain'], [
  ['Algebraic fraction', 'Алгебраическая дробь', 'An algebraic fraction has algebraic expressions in its numerator and denominator, and it is defined only when the denominator is not zero. If both are polynomials, it is called a rational expression.', 'Алгебраическая дробь (algebraic fraction) — дробь, в числителе и знаменателе которой стоят алгебраические выражения. Она определена только тогда, когда знаменатель не равен нулю. Если и числитель, и знаменатель — многочлены, такую дробь называют рациональным выражением.', '(x + 1)/(x − 2) is defined only for x ≠ 2. For x = 5, its value is (5 + 1)/(5 − 2) = 6/3 = 2.', 'Дробь (x + 1)/(x − 2) определена только при x ≠ 2. При x = 5 её значение равно (5 + 1)/(5 − 2) = 6/3 = 2.', 'You can divide each term of the numerator by the denominator, but the denominator cannot be split: (x + 1)/x = x/x + 1/x = 1 + 1/x for x ≠ 0. But 1/(x + 1) is not 1/x + 1: at x = 1, the left side is 0.5 and the right side is 2.', 'Каждое слагаемое числителя можно разделить на знаменатель, а знаменатель разбивать нельзя: (x + 1)/x = x/x + 1/x = 1 + 1/x при x ≠ 0. Но 1/(x + 1) — не то же, что 1/x + 1: при x = 1 левая часть равна 0,5, а правая — 2.'],
  ['Rational equation', 'Рациональное уравнение', 'A rational equation is an equation that contains algebraic fractions with the variable in a denominator. Its solutions must be values that are allowed in the original expressions.', 'Рациональное уравнение — уравнение, в котором есть алгебраические дроби с переменной в знаменателе. Решением может быть только значение, допустимое в исходных выражениях.', 'For 2x/(x − 2) = 4 + 4/(x − 2), first note that x ≠ 2. Multiplying by x − 2 gives 2x = 4(x − 2) + 4, so 2x = 4x − 4 and x = 2. This value is excluded, so the equation has no solution.', 'Для уравнения 2x/(x − 2) = 4 + 4/(x − 2) сначала запиши, что x ≠ 2. Умножь на x − 2: 2x = 4(x − 2) + 4, откуда 2x = 4x − 4 и x = 2. Это недопустимое значение, поэтому решений нет.', 'If clearing denominators leaves a statement that is true for every x, such as x = x, the solution is every allowed value, not every real number. For x/x = 1, the solution is all x ≠ 0.', 'Если после избавления от знаменателей получается верное при любом x равенство (например, x = x), решением служат все допустимые значения. Это не все действительные числа. Для x/x = 1 решение — все x ≠ 0.'],
  ['Excluded value', 'Недопустимое значение', 'A value of the variable for which the expression or equation is not defined, usually because a denominator would be zero.', 'Значение переменной, при котором выражение или уравнение не имеет смысла, обычно потому, что знаменатель стал бы равен нулю.', '(x² − 4)/(x − 2) = x + 2 only for x ≠ 2. At x = 2, the left side is 0/0, which is undefined, even though x + 2 = 4.', '(x² − 4)/(x − 2) = x + 2 только при x ≠ 2. При x = 2 левая часть равна 0/0, то есть не определена, хотя x + 2 = 4.', 'A zero numerator does not always give a solution. In (x² − 1)/(x − 1) = 0, the numerator is zero at x = 1 and x = −1, but x = 1 is excluded, so the only solution is x = −1.', 'Нуль в числителе не всегда даёт решение. В уравнении (x² − 1)/(x − 1) = 0 числитель равен нулю при x = 1 и x = −1, но x = 1 — недопустимое значение, поэтому решение только x = −1.'],
]);
group(['variation'], [
  ['Direct proportion', 'Прямая пропорциональность', 'Two variables are in direct proportion if their ratio is constant, so y/x = k and y = kx for a fixed number k. If x is multiplied by a number, y is multiplied by the same number.', 'Две величины связаны прямой пропорциональностью, если их отношение постоянно: y/x = k, то есть y = kx при фиксированном числе k. Если x умножить на число, то y умножится на то же число.', 'If y = 3x, then x = 2 gives y = 6 and x = 4 gives y = 12. Doubling x doubles y.', 'Если y = 3x, то при x = 2 получаем y = 6, а при x = 4 — y = 12. Удвоение x удваивает y.', 'A straight line is not always direct proportion. For y = 3x + 2, the ratio y/x is not constant: it is 5 when x = 1, but 4 when x = 2.', 'Прямая линия не всегда означает прямую пропорциональность. Для y = 3x + 2 отношение y/x не постоянно: при x = 1 оно равно 5, а при x = 2 — 4.'],
  ['Inverse proportion', 'Обратная пропорциональность', 'Two variables are in inverse proportion if multiplying one of them by a non-zero number divides the other by the same number. This gives y = k/x for a fixed non-zero k, so xy is always the same number.', 'Две величины связаны обратной пропорциональностью, если при умножении одной из них на ненулевое число другая делится на то же число. Тогда y = k/x при фиксированном ненулевом k, и произведение xy не меняется.', 'If xy = 12, then x = 3 gives y = 4 and x = 6 gives y = 2. Doubling x halves y.', 'Если xy = 12, то при x = 3 получаем y = 4, а при x = 6 — y = 2. Удвоение x уменьшает y вдвое.', 'For y = k/x, x cannot be 0, so there is no output at x = 0. Do not write y = 0 there. The graph never touches either axis.', 'Для y = k/x переменная x не может быть равна нулю, поэтому при x = 0 значения y нет. Не пиши y = 0. График никогда не касается ни одной из осей.'],
  ['Constant of proportionality', 'Коэффициент пропорциональности', 'The fixed number k in a model such as y = kx, y = kx² or y = k/x. It has the same value for every pair of values in that model.', 'Постоянное число k в формуле вида y = kx, y = kx² или y = k/x. Для любой пары значений x и y в этой модели k имеет одно и то же значение.', 'In y = kx, the pair x = 4, y = 10 gives k = 10 ÷ 4 = 2.5. In y = k/x, the same pair gives k = 4 × 10 = 40.', 'В модели y = kx пара x = 4, y = 10 даёт k = 10 ÷ 4 = 2,5. В модели y = k/x та же пара даёт k = 4 × 10 = 40.', 'Only in y = kx is k the gradient (slope) of the graph. For y = kx², the graph is a parabola, and for y = k/x it is a hyperbola, so k is not a slope there.', 'Только для y = kx число k — угловой коэффициент (gradient) прямой. Для y = kx² график — парабола, а для y = k/x — гипербола, поэтому там k не задаёт наклон прямой.'],
]);
group(['rationalFunctions'], [
  ['Asymptote', 'Асимптота', 'Extended: an asymptote is a line that a graph gets closer and closer to. A vertical asymptote x = h means |y| grows without limit as x gets close to h. A horizontal asymptote y = k means y gets close to k as x becomes very large or very negative.', 'Extended: асимптота — прямая, к которой график приближается всё ближе. Вертикальная асимптота x = h: при x, близком к h, |y| неограниченно растёт. Горизонтальная асимптота y = k: при очень больших по модулю x значения y приближаются к k.', 'For y = 6/x, the asymptotes are the axes: x = 0 and y = 0.', 'Для y = 6/x асимптоты — оси координат: x = 0 и y = 0.', 'A graph can cross a horizontal asymptote. For example, y = x/(x² + 1) passes through (0, 0), which lies on y = 0. A graph never crosses a vertical asymptote, because the function is undefined on that line.', 'График может пересекать горизонтальную асимптоту. Например, y = x/(x² + 1) проходит через точку (0; 0), которая лежит на прямой y = 0. Вертикальную асимптоту график не пересекает, потому что функция на этой прямой не определена.'],
  ['Rational function', 'Дробно-рациональная функция', 'Extended: a function written as P(x)/Q(x), where P(x) and Q(x) are polynomials and Q(x) is not zero.', 'Extended: функция вида P(x)/Q(x), где P(x) и Q(x) — многочлены, а знаменатель Q(x) не равен нулю.', 'For f(x) = (2x + 1)/(x − 3), f(4) = 9/1 = 9. But f(3) does not exist, because the denominator is 0 there.', 'Для f(x) = (2x + 1)/(x − 3) получаем f(4) = 9/1 = 9. А f(3) не существует, потому что знаменатель при x = 3 равен 0.', 'A fraction with x does not always give a rational function. For example, √x/x is not one, because √x is not a polynomial. A polynomial also counts, because it can be written over 1.', 'Не каждая дробь с переменной задаёт дробно-рациональную функцию. Например, у функции √x/x числитель √x — не многочлен, поэтому она не дробно-рациональная. Многочлен тоже подходит: его можно записать дробью со знаменателем 1.'],
]);
group(['exponential'], [
  ['Exponential function', 'Показательная функция', 'Extended: a function in which x is in the exponent and the base b is a fixed positive number that is not 1. The basic form is f(x) = bˣ, with b > 0 and b ≠ 1.', 'Extended: функция, в которой x стоит в показателе степени, а основание b — постоянное положительное число, не равное 1. Основной вид: f(x) = bˣ, где b > 0 и b ≠ 1.', 'For f(x) = 2ˣ, x = 0, 1 and 2 give 1, 2 and 4. Each increase of x by 1 multiplies the output by 2.', 'Для f(x) = 2ˣ при x = 0, 1 и 2 получаем 1, 2 и 4. Каждое увеличение x на 1 умножает значение функции на 2.', 'x² is a power function, not an exponential one. For x = 1, 2 and 3, x² gives 1, 4 and 9, so the ratio of consecutive outputs changes (×4, then ×2.25). For 2ˣ, the outputs at x = 1, 2 and 3 are 2, 4 and 8, and each is 2 times the previous one.', 'x² — степенная функция (power function), а не показательная. Значения x² при x = 1, 2 и 3 равны 1, 4 и 9. Отношение соседних значений меняется: в 4 раза, потом в 2,25 раза. Значения 2ˣ при x = 1, 2 и 3 равны 2, 4 и 8, и каждое в 2 раза больше предыдущего.'],
]);
group(['optimisation'], [
  ['Linear programming', 'Линейное программирование', 'Linear programming is a method of finding the largest or smallest value of a linear objective function when the choices must satisfy linear constraints.', 'Линейное программирование — это метод поиска наибольшего или наименьшего значения линейной целевой функции при линейных ограничениях.', 'Sam has US$40 to spend on notebooks and pens, and wants as many items as possible. Let x be the number of notebooks and y the number of pens. The model is: maximise N = x + y, subject to 4x + 2y ≤ 40, x ≥ 0 and y ≥ 0.', 'У Сэма есть 40 долл. США на тетради и ручки, и он хочет купить как можно больше предметов. Пусть x — число тетрадей, y — число ручек. Модель такая: максимизировать N = x + y при 4x + 2y ≤ 40, x ≥ 0 и y ≥ 0.', 'A model can have no solution at all. For x + y ≥ 8 and x + y ≤ 6, no point satisfies both conditions, so the feasible region is empty.', 'Модель может не иметь решения. При x + y ≥ 8 и x + y ≤ 6 ни одна точка не выполняет оба условия, поэтому допустимой области нет.', 'optimisation'],
  ['Constraint', 'Ограничение', 'A constraint is a condition that every allowed choice of the variables must satisfy.', 'Ограничение — это условие, которому должен удовлетворять каждый допустимый выбор переменных.', 'Each notebook costs US$4, so x notebooks cost 4x. Each pen costs US$2, so y pens cost 2y. The constraint 4x + 2y ≤ 40 means the total cost is at most US$40.', 'Тетрадь стоит 4 долл. США, поэтому x тетрадей стоят 4x. Ручка стоит 2 долл. США, поэтому y ручек стоят 2y. Ограничение 4x + 2y ≤ 40 значит, что общая стоимость не больше 40 долл. США.', 'A constraint decides which choices are allowed. The objective function decides which allowed choice is best.', 'Ограничение определяет, какие выборы допустимы. Целевая функция определяет, какой из допустимых выборов лучший.', 'optimisation'],
  ['Feasible region', 'Допустимая область', 'The feasible region is all the points that satisfy every constraint at the same time.', 'Допустимая область — это все точки, которые одновременно удовлетворяют каждому ограничению.', 'For x ≥ 0, y ≥ 0 and 4x + 2y ≤ 40, the vertices of the region are (0, 0), (10, 0) and (0, 20).', 'При x ≥ 0, y ≥ 0 и 4x + 2y ≤ 40 вершины области: (0, 0), (10, 0) и (0, 20).', 'The feasible region is where all the allowed areas overlap, not their union. A boundary line belongs to the region only when the inequality uses ≤ or ≥.', 'Допустимая область — это общая часть областей, которые задают ограничения, а не их объединение. Граничная прямая входит в область, только если неравенство нестрогое (со знаком ≤ или ≥).', 'optimisation'],
  ['Objective function', 'Целевая функция', 'The objective function is the rule that gives one number for each choice of the variables. This number is to be maximised or minimised.', 'Целевая функция — это правило, которое каждому выбору переменных ставит в соответствие одно число. Это число нужно максимизировать или минимизировать.', 'For Sam\'s shopping, N(x, y) = x + y counts the items. If Sam buys 2 notebooks and 10 pens, the cost is 2 × 4 + 10 × 2 = US$28, and N = 2 + 10 = 12 items.', 'Для покупок Сэма N(x, y) = x + y считает предметы. Если Сэм купит 2 тетради и 10 ручек, они стоят 2 × 4 + 10 × 2 = 28 долл. США, а N = 2 + 10 = 12 предметов.', 'N(x, y) = x + y is the rule. 12 is a value the rule gives for one choice. (2, 10) is the choice of variables. These are three different things.', 'N(x, y) = x + y — это правило. 12 — значение целевой функции для одного выбора. (2, 10) — выбор переменных. Это три разные вещи.', 'optimisation'],
  ['Optimal solution', 'Оптимальное решение', 'An optimal solution is a feasible choice of the variables that gives the best value of the objective function over the whole feasible region.', 'Оптимальное решение — это допустимый выбор переменных, при котором целевая функция принимает наилучшее значение во всей допустимой области.', 'For N = x + y in Sam\'s region, the optimal solution is (0, 20): no notebooks and 20 pens, which gives the largest value N = 20.', 'Для N = x + y в задаче Сэма оптимальное решение — (0, 20): ни одной тетради и 20 ручек, и тогда N = 20 — наибольшее значение.', 'A feasible choice is not automatically optimal. The choice (10, 0) is allowed for Sam, but it gives only N = 10.', 'Допустимый выбор не обязательно оптимален. Выбор (10, 0) для Сэма допустим, но даёт только N = 10.', 'optimisation'],
]);
group(['signs', 'ruSigns'], [
  ['Critical value', 'Граничное значение для метода интервалов', 'A value of x at which the expression is zero or undefined. These values split the number line into intervals.', 'Значение x, при котором выражение равно нулю или не определено. Такие значения делят числовую прямую на промежутки.', 'For (x − 1)/(x + 2), the critical values are 1 (the fraction is 0) and −2 (the fraction is undefined).', 'Для (x − 1)/(x + 2) граничные значения: 1 (дробь равна 0) и −2 (дробь не определена).', 'Only zeros of the denominator are excluded. A zero of the numerator makes the fraction 0, and that value can be in the answer.', 'Из ответа исключают только нули знаменателя. Нуль числителя делает дробь равной 0, и такое значение может войти в ответ.'],
  ['Sign chart', 'Таблица знаков; метод интервалов', 'A diagram or table recording where an expression and its factors are positive, negative, zero or undefined.', 'Схема или таблица, показывающая, где выражение и его множители положительны, отрицательны, равны нулю или не определены.', 'For (x − 1)/(x + 2), signs from left to right are +, −, + on (−∞, −2), (−2, 1), (1, ∞).', 'Для (x − 1)/(x + 2) знаки слева направо: +, −, + на (−∞, −2), (−2, 1), (1, ∞).', 'Testing one point works only after all zeros and discontinuities have split intervals where the sign cannot change.', 'Одна пробная точка достаточна только после выделения всех нулей и разрывов, разделяющих интервалы постоянного знака.'],
  ['Boundary inclusion', 'Включение границы в решение', 'Whether the end of an interval belongs to the answer. A root is included for ≤ or ≥ and excluded for < or >, as long as the expression is defined there.', 'Входит ли конец промежутка в ответ. Корень входит при ≤ или ≥ и не входит при < или >, если выражение в этой точке определено.', 'For (x − 3)/(x + 1) < 0, the root x = 3 is excluded, because the inequality is strict.', 'Для (x − 3)/(x + 1) < 0 корень x = 3 не входит в ответ, потому что неравенство строгое.', 'On a number line, a filled circle marks an included root, such as x = 1 in the main example, and an open circle marks an excluded value, such as x = −2.', 'На числовой прямой закрашенная точка (filled circle) — это корень, который входит в ответ, например x = 1 из основного примера. Выколотая точка (open circle) — это недопустимое значение, например x = −2.'],
]);

const modelNotes: Record<string, { en: string; ru: string }> = {
  Fraction: { en: 'The shaded strip assumes equal parts of the same whole. Division extends the idea beyond that picture.', ru: 'полоска показывает равные доли одного целого. Деление распространяет эту идею за пределы этого рисунка.' },
  Bearing: { en: 'These exercises use a flat map with parallel north lines; routes on a curved Earth require additional navigation conventions.', ru: 'Здесь используется плоская карта с параллельными направлениями севера; на сферической Земле нужны дополнительные навигационные соглашения.' },
  'Linear programming': { en: 'The diagram allows real-valued choices. If items must be whole numbers, state and check the integer restriction separately.', ru: 'Диаграмма допускает действительные значения. Если количество предметов должно быть целым, это ограничение задают и проверяют отдельно.' },
  'Feasible region': { en: 'The drawn example is bounded. Other systems can give an empty or unbounded feasible set.', ru: 'Показанная область ограничена. Другая система может задавать пустую или неограниченную область.' },
  'Period (Extended)': { en: 'For A sin(Bx) + D, the formula 360°/|B| is the fundamental period only when A ≠ 0 and B ≠ 0, with x measured in degrees.', ru: 'Для A sin(Bx) + D формула 360°/|B| даёт основной период только при A ≠ 0 и B ≠ 0, если x измеряется в градусах.' },
  'Direct proportion': { en: 'A real-world proportional model assumes a fixed ratio on a stated range; measurement error or changing conditions can break that assumption.', ru: 'Модель реальной пропорциональности предполагает постоянное отношение на указанном диапазоне; погрешности и изменение условий могут нарушать это предположение.' },
  'Exponential function': { en: 'A growth model assumes a fixed multiplier over equal input steps. A few observations do not establish that it remains valid indefinitely.', ru: 'Модель роста предполагает постоянный множитель при равных шагах аргумента. Несколько наблюдений не доказывают её применимость на неограниченное время.' },
};
for (const [term, model] of Object.entries(modelNotes)) if (reviewedTerms[term]) reviewedTerms[term].review.model = model;

export function defineTerm(term: string): Term {
  const value = reviewedTerms[term];
  if (!value) throw new Error(`Missing reviewed mathematics definition: ${term}`);
  return value;
}
